async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const btn = [...document.querySelectorAll('button')].find(b => b.textContent.trim() === '查看遥测');
  btn.click();
  await wait(60);
  const dlg = document.querySelector('[role=dialog]');
  const grab = () => ({
    dialog: !!dlg,
    label: dlg && dlg.getAttribute('aria-label'),
    text: dlg && dlg.innerText,
    retry: (() => {
      const r = [...dlg.querySelectorAll('button')].find(b => b.textContent.trim() === '重试');
      if (!r) return 'absent';
      const cs = getComputedStyle(r);
      return { disabled: r.disabled, display: cs.display, visibility: cs.visibility, hidden: r.hasAttribute('hidden') };
    })()
  });
  const t0 = grab();
  await wait(500);
  const t1 = grab();
  return { at60ms: t0, at560ms: t1 };
}

async () => {
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const dlg = document.querySelector('[role=dialog]');
  const find = (t) => [...dlg.querySelectorAll('button')].find(b => b.textContent.trim() === t);
  find('重试').click();
  await wait(60);
  const r = find('重试');
  const at60 = { text: dlg.innerText, retry: r ? { disabled: r.disabled, display: getComputedStyle(r).display } : 'absent' };
  await wait(700);
  const at760 = {
    text: dlg.innerText,
    html: dlg.innerHTML,
    strongs: [...dlg.querySelectorAll('strong')].map(s => s.textContent)
  };
  return { at60, at760 };
}
